insert into action_plans (title, description, key_result_id, objective_id, team_id, owner_id, external_assignees, status, priority, bucket, labels, checklist, start_date, due_date, external_id, external_source, data_source, created_by) values ('Sales 통계 구축 + Sales CRM + OKR = 클로드AI 기획', '세일즈 통계 대시보드 구축 : 구매팀 CRM , 닷비즈 고도화로 늦어짐', '00000000-0000-4000-8000-0000000000d5', null, (select id from teams where slug='gst'), (select id from public.users where email='cb.park@ohmyhotel.com'), array['Younggeun Choi (Justin)','Dang Minh Duc (Ben)','HooiWem Tan (Grace)','Park Changbae (Aiden)','Jungwon Yoon (Sophia)']::text[], 'in_progress', 'important', '진행 50% 이상 Action Plan', array['System Plan','AI','Q1','KR5 Revunue260억']::text[], '[{"id":"c0","text":"전체 세일즈팀 점검 + 피드백 받기 - 2025년 12월 30일","done":false},{"id":"c1","text":"2차 피드백","done":false},{"id":"c2","text":"ChatGPT + 클로드 : 프로트타입 만들기 - 2025년 12월 25일","done":false},{"id":"c3","text":"1차 피드백","done":false},{"id":"c4","text":"3차 대표님 피드백","done":false},{"id":"c5","text":"2026년 5월 8일 Sales CRM 기획 시작","done":false},{"id":"c6","text":"점검 및 기획 마무리","done":false},{"id":"c7","text":"클로드 AI 기획 3주 소요 : 5월 말까지 마무리 하기","done":false}]'::jsonb, '2025-12-25', '2026-05-29', 'jfQV8dUwE0KRUthMzAf4jckAFqIQ', 'planner', 'planner', (select id from public.users where email='cb.park@ohmyhotel.com'));
insert into action_plans (title, description, key_result_id, objective_id, team_id, owner_id, external_assignees, status, priority, bucket, labels, checklist, start_date, due_date, external_id, external_source, data_source, created_by) values ('Operation 최적화 작업(맨파워 활용)', 'SET (DI + OP)를 최대한 효율적인 부서로 관리 및 진화 -> 최적화 최적화된 팀 & 맴버를 활용하여 SCM + SALES : 영업부서가 필요한 작업들을 효율적으로 처리하는데 목적을 둠 제1원칙사고 (일론머스크): 제1원칙 사고(First Principle Thinking)는 복잡한 문제를 가장 기본적인 구성 요소(근본 원리)로 분해한 뒤, 그 핵심 진실로부터 새로운 해결책을 구축하는 사고방식으로, 일론 머스크가 널리 알려지게 했으며 기존의 통념이나 유추적 사고에서 벗어나 ''왜?''라는 질문', '00000000-0000-4000-8000-0000000000d2', null, (select id from teams where slug='gst'), (select id from public.users where email='cb.park@ohmyhotel.com'), array['Duong To Nguyen (Nancy)','Tu Huynh (Vicky)','HooiWem Tan (Grace)','Park Changbae (Aiden)','Jungwon Yoon (Sophia)','Nguyễn Trọng Nhân (Karl)','Jackie']::text[], 'in_progress', 'urgent', '진행 50% 이상 Action Plan', array['RPA','AI','Optimization','KR2 7000']::text[], '[{"id":"c0","text":"SO 최적화 작업 : 기존 메뉴얼 (수동작업)을 RPA + AI 를 통해 최대한 효율적으로 변경","done":false},{"id":"c1","text":"전체적인 OP구조 : 콜 대응 구조 최적화 + OP 최적화 + C를 위한 챗봇+AI -> 작업중","done":false},{"id":"c2","text":"Slena -> SCD / Suyaa -> Sales","done":false},{"id":"c3","text":"DO 최적화 작업 : 기존 메뉴얼 (수동작업)을 RPA + AI 를 통해 최대한 효율적으로 변경","done":false},{"id":"c4","text":"SOP + SLA : 작업중","done":false}]'::jsonb, null, null, 'sLQplDBcVECyCh_i8oiPK8kALdLB', 'planner', 'planner', (select id from public.users where email='cb.park@ohmyhotel.com'));
insert into action_plans (title, description, key_result_id, objective_id, team_id, owner_id, external_assignees, status, priority, bucket, labels, checklist, start_date, due_date, external_id, external_source, data_source, created_by) values ('2026 Channel Marketing - Promotion', 'Promotion Planning We will prepare various promotions on an annual, quarterly, and monthly basis, segmented by channel, country, and region. Korea promotions: JW Japan promotions: Won, SW Vietnam promotions: Anna Other Southeast Asia markets: Sang Hong Kong & Japan: Ella', '00000000-0000-4000-8000-0000000000d5', null, (select id from teams where slug='gst'), (select id from public.users where email='cb.park@ohmyhotel.com'), array['Sang Kyu Yoo (Sang)','Lim Dabin (Ella)','Park Sungwoo','Kim Jaewon (Jw Kim)','HooiWem Tan (Grace)','Park Changbae (Aiden)','Won Jiyeon','Pham Thi Phuong Anh (Anna)']::text[], 'in_progress', 'important', '진행 30% Action Plan', array['Marketing Plan','2026','KR5 Revunue260억']::text[], '[{"id":"c0","text":"채널 별 타켓팅 프로모션 준비 : OTA 위주 \"메이투안, 취날, 플리기, 스트립\" 등 - 마크업 다운 스페셜 프로모션으로 진행","done":false},{"id":"c1","text":"2026년 2월 춘절 맞이 얼리버드 프로모션 준비 : Chinese New Year Special : 5박이상","done":false},{"id":"c2","text":"장박 할인 프로모션 요청하기 : 1월 프로모션~ WITH GBO - 2월 진행완료","done":false},{"id":"c3","text":"Summer Vacation Deal (3박↑ 할인) : Family Room / Extra Bed 무료","done":false},{"id":"c4","text":"짧은 휴가용 Weekend Deal","done":false},{"id":"c5","text":"Fast Booking (72시간 한정 특가)","done":false},{"id":"c6","text":"Family Room / Extra Bed 무료 : Family Benefit (조식/엑스트라베드)","done":false},{"id":"c7","text":"주중 체크인 할인 (중국은 주말보다 분산 수요 큼)","done":false},{"id":"c8","text":"추가 신규 프로모션 : 벚꽃시즌 : 벚꽃/도심 호텔 특가 (서울·부산·도쿄·오사카)","done":false},{"id":"c9","text":"Flash Sale (재고 소진용), Non-refundable 초특가","done":false},{"id":"c10","text":"추가 신규 프로모션 : 봄 방학","done":false},{"id":"c11","text":"2025년 12월 : 겨울방학 시즌 대비 일본 온천 호텔 프로모션 체크 - 리스트 받","done":false},{"id":"c12","text":"2026년 허니문 호텔 얼리버드 프로모션 준비 - 베트남 완료, 한국 완료 - 2026년 1월 12일","done":false},{"id":"c13","text":"Business Travel Deal (조식+Late Checkout) : Business + Leisure (출장 겸 여행)","done":false},{"id":"c14","text":"조식 포함 + Late Checkout","done":false},{"id":"c15","text":"여름 성수기 얼리버드 프로모션 : 3월 진행","done":false},{"id":"c16","text":"(마감임박)더데이 프로모션 중국 5월 노동절","done":false},{"id":"c17","text":"Long Stay (5/7/14박 할인)","done":false},{"id":"c18","text":"단풍(10–11월) 시즌 특가","done":false},{"id":"c19","text":"하드블럭 프로모션","done":false}]'::jsonb, '2026-01-05', '2026-12-31', 'rxtFSVP_l0eanRdihVk7ockAHxGa', 'planner', 'planner', (select id from public.users where email='cb.park@ohmyhotel.com'));
