insert into action_plans (title, description, key_result_id, objective_id, team_id, owner_id, external_assignees, status, priority, bucket, labels, checklist, start_date, due_date, external_id, external_source, data_source, created_by) values ('닷 비즈 고도화 작업', '닷비즈 고도화 작업 : SaaS - B2B2C - White Label 등 (구매 + 판매 => 마켓플레이스) 필요내용 상세파악 : 결재수단 보안 : 각 국가별 PG사 연동 베트남 OnePay -> 동남아시아 전체 사용 가능한 PayGate인가?? 싱가포르는??? 중화권은? Alipay or Wechat Pay 인디아, 중동은??', '00000000-0000-4000-8000-0000000000d1', null, (select id from teams where slug='gst'), (select id from public.users where email='cb.park@ohmyhotel.com'), array['Younggeun Choi (Justin)','HooiWem Tan (Grace)','Park Changbae (Aiden)','Thinh Vo (Joseph)','Jungwon Yoon (Sophia)','Jackie']::text[], 'completed', 'important', '마무리', array['System Plan','2026','KR1 1000']::text[], '[{"id":"c0","text":"대표님 피드백 완료 (세틀먼트)","done":true},{"id":"c1","text":"1차 고도화 작업 완료","done":true},{"id":"c2","text":"CTO, Julia 2차까지 피드백 완료","done":true},{"id":"c3","text":"대표님 보고 완료","done":true},{"id":"c4","text":"OKR발표 + GBO 미팅 : 2026년 1월 7일","done":true},{"id":"c5","text":"프로트타입 + 디다 & 웹베즈 참고 : GBO 미팅 + 보완 -> 이번달까지 보완하기 + 얼렛기능 넣기","done":true},{"id":"c6","text":"고객친화적모델구상 - ChatGPT + 클로드 AI : 2026년 1월 8일","done":true},{"id":"c7","text":"초기 셋팅 CTO님 피드백 받기 -> 바로 진행 가능함","done":true}]'::jsonb, '2026-01-08', '2026-04-30', 'jyKl8sS5wUOHY_dJcniu7ckAGOaM', 'planner', 'planner', (select id from public.users where email='cb.park@ohmyhotel.com'));
insert into action_plans (title, description, key_result_id, objective_id, team_id, owner_id, external_assignees, status, priority, bucket, labels, checklist, start_date, due_date, external_id, external_source, data_source, created_by) values ('월별 & 분기별 OKR+CFR 점검', '월별 & 분기별로 전체 OKR+CFR 점검을 통해 KR 달성율 최대한으로 끌어 올리기', '00000000-0000-4000-8000-0000000000d5', null, (select id from teams where slug='gst'), (select id from public.users where email='cb.park@ohmyhotel.com'), array['Yun Hye Yeong ̣(Jane)','Dang Minh Duc (Ben)','Son Yeong Eun (Jasmine)','Tu Huynh (Vicky)','HooiWem Tan (Grace)','Park Changbae (Aiden)','Jackie']::text[], 'in_progress', 'important', '진행 30% Action Plan', array['2026','Optimization','OKR+CFR','KR5 Revunue260억','OKR+CFR']::text[], '[{"id":"c0","text":"스텝별 1월 OKR+CFR : 2월 10일~ 3일 간","done":false},{"id":"c1","text":"스텝별 2월 OKR+CFR : 3월 17일~3일간","done":false},{"id":"c2","text":"팀 전체 1분기 OKR+CFR : 4월 초 PPT 준비 2장 , CEO OKR GAP 확인, 업데이트","done":false},{"id":"c3","text":"스텝별 5월 OKR+CFR :","done":false},{"id":"c4","text":"팀 전체 2분기 OKR+CFR :","done":false},{"id":"c5","text":"스텝별 4월 OKR+CFR : 5월 5일 ~7일 3일 간","done":false}]'::jsonb, null, null, 'E-cVuUdhR0moAcnLecXw4MkAIebU', 'planner', 'planner', (select id from public.users where email='cb.park@ohmyhotel.com'));
insert into action_plans (title, description, key_result_id, objective_id, team_id, owner_id, external_assignees, status, priority, bucket, labels, checklist, start_date, due_date, external_id, external_source, data_source, created_by) values ('고객사 영업 가이드 라인 완성하기', 'Tier 별 라인 만들기 (Global Sales Team) Tier0 50억 이상 : Make My Trip, Traveloka, Ctrip VN Tier1 20억 이상 : DIDA, Convergent, Traveloka, PKFARE, Tourmind, Tiket.com Tier2 10~20억 : QIYOUJI Tier3 1~10억 : Vietravel Tier4 1억 미만 :', '00000000-0000-4000-8000-0000000000d3', null, (select id from teams where slug='gst'), (select id from public.users where email='cb.park@ohmyhotel.com'), array['Dang Minh Duc (Ben)','HooiWem Tan (Grace)','Park Changbae (Aiden)']::text[], 'in_progress', 'important', '진행 30% Action Plan', array['Marketing Plan','2026','KR3 TTV50억 * 3']::text[], '[{"id":"c0","text":"Tier2 : 월 수탁고 10~20억, Manager 라인 = 안정적인 매출 최적화","done":false},{"id":"c1","text":"Tier4 : 월 수탁고 1억 미만, 최소한의 OP운영 = 최소유지관리","done":false},{"id":"c2","text":"Tier3 : 월 수탁고 1~10억, Team member 라인 = 확장 및 표준화 관리","done":false},{"id":"c3","text":"Tier0 : 월 수탁고 50억 초과, C레벨 라인 만들기 (CEO, COO) = 핵심파트너","done":false},{"id":"c4","text":"AI 대시보드에 추가하여 관리 필요","done":false},{"id":"c5","text":"Tier1 : 월 수탁고 20~50억, Director 라인(VP) = 선택적 집중 성장","done":false}]'::jsonb, null, null, 'v9_gYXesWk6fKo7Lqrtw-skAHzYI', 'planner', 'planner', (select id from public.users where email='cb.park@ohmyhotel.com'));
insert into action_plans (title, description, key_result_id, objective_id, team_id, owner_id, external_assignees, status, priority, bucket, labels, checklist, start_date, due_date, external_id, external_source, data_source, created_by) values ('B2B Key Account Specialist', '지역별 PIC 교육 + 성공사례 + 실패사례', '00000000-0000-4000-8000-0000000000d5', null, (select id from teams where slug='gst'), (select id from public.users where email='cb.park@ohmyhotel.com'), array['Park Changbae (Aiden)']::text[], 'not_started', 'important', '진행 10% Action Plan', array['2026','HR','KR5 Revunue260억']::text[], '[{"id":"c0","text":"System 교육","done":false},{"id":"c1","text":"Sales Skill 교육","done":false},{"id":"c2","text":"AI 리터러시","done":false},{"id":"c3","text":"그 외 다양한 업무스킬 교육","done":false},{"id":"c4","text":"Data 리터러시","done":false},{"id":"c5","text":"각 국가별 SCM 호텔 교육 받기","done":false}]'::jsonb, null, null, 'yE6cbVjCP0CnlE3OBnUVhMkAFrsJ', 'planner', 'planner', (select id from public.users where email='cb.park@ohmyhotel.com'));
insert into action_plans (title, description, key_result_id, objective_id, team_id, owner_id, external_assignees, status, priority, bucket, labels, checklist, start_date, due_date, external_id, external_source, data_source, created_by) values ('신규 시장 진입', '아시아 신규 시장 진입 + 중동 까지 = 아시아 베드 뱅크 넘버원', '00000000-0000-4000-8000-0000000000d4', null, (select id from teams where slug='gst'), (select id from public.users where email='cb.park@ohmyhotel.com'), array['Dang Minh Duc (Ben)','HooiWem Tan (Grace)','Park Changbae (Aiden)']::text[], 'in_progress', 'important', '진행 50% 이상 Action Plan', array['Destination','2026','KR4 중화권65%']::text[], '[{"id":"c0","text":"SEA 말레이시아, 싱가포르 : Mayflower , Staylah 등","done":false},{"id":"c1","text":"Rusia : Ostrovok 등 - 벤 컨택 중","done":false},{"id":"c2","text":"SEA 인도네시아 : Traveloka, Tiket.com, Nusatrip 등","done":false},{"id":"c3","text":"India : Make My Trip 등","done":false},{"id":"c4","text":"SEA 베트남 : Chudu24+, Ivivu, Vietravel, Mustgo, Vntrip 등","done":false},{"id":"c5","text":"중동 (UAE, 카타르, 사우디) : 싱가포르 에서 담당","done":false},{"id":"c6","text":"유럽 : 터키(서아시아) PAX2NIGHT","done":false},{"id":"c7","text":"SEA 태국 : 벤 진행 중","done":false}]'::jsonb, null, null, 'rO6GlKmGqEitI7rVQQh568kACZpS', 'planner', 'planner', (select id from public.users where email='cb.park@ohmyhotel.com'));
insert into action_plans (title, description, key_result_id, objective_id, team_id, owner_id, external_assignees, status, priority, bucket, labels, checklist, start_date, due_date, external_id, external_source, data_source, created_by) values ('MS365 생태계 구축 + OKR + CFR + RPA + AI = 업무 효율성 증가', 'MS365 생태계 안에서 Task 중심의 운영 : 2026년 전사 업무를 하나의 툴과 워크플로우로 통합', '00000000-0000-4000-8000-0000000000d5', null, (select id from teams where slug='gst'), (select id from public.users where email='cb.park@ohmyhotel.com'), array['Park Changbae (Aiden)']::text[], 'in_progress', 'important', '진행 80% 이상 Action Plan', array['Requirements','Q1','KR5 Revunue260억']::text[], '[{"id":"c0","text":"Power BI 운영 : 통계 사용 -> 엘리스 시스템 세일즈 대시보드 구축 -> CTO 피드백","done":false},{"id":"c1","text":"Viva Goal 팀즈 확인하기 - 현재 불가(튜=추후확인)","done":false},{"id":"c2","text":"MS Tool (Excel, PPT) : 생태계 내에서만 자료 만들기","done":false},{"id":"c3","text":"OKR+CFR 팀즈 운영 결정 : 2026년 1월 1일 부터 진행","done":false},{"id":"c4","text":"Report : 보고체계단순화 -> 팀즈사용 가능여부 확인 하기 -> 세일즈 리포트 포함하여 확인","done":false},{"id":"c5","text":"RPA+AI : 효율성 극대화","done":false},{"id":"c6","text":"OKR+CFR : Team에서 해결 : 전사 사용으로 빠르게 전환하기 : 브레인스토밍 2차 완료","done":false}]'::jsonb, null, null, '-OEQ6TrTJUWL0tvRBLjWKskAHfHy', 'planner', 'planner', (select id from public.users where email='cb.park@ohmyhotel.com'));
insert into action_plans (title, description, key_result_id, objective_id, team_id, owner_id, external_assignees, status, priority, bucket, labels, checklist, start_date, due_date, external_id, external_source, data_source, created_by) values ('Q1, Q2 내부 마켓팅(고객사 교육) 준비', '분기별 SCM 교육 하기 : 지역별 고객사 + 국가별 특징 등 팀별 피드백 받아서 + 고객사 문의시 활용 고객사 답변 -> 다시 각 SCM에게 공유~ 이게 바로 내부 마켓팅이지`~~~~', '00000000-0000-4000-8000-0000000000d2', null, (select id from teams where slug='gst'), (select id from public.users where email='cb.park@ohmyhotel.com'), array['Sang Kyu Yoo (Sang)','Park Sungwoo','Kim Jaewon (Jw Kim)','HooiWem Tan (Grace)','Park Changbae (Aiden)','Won Jiyeon','Jackie']::text[], 'in_progress', 'important', '진행 30% Action Plan', array['Marketing Plan','Q1','Q2','KR2 7000']::text[], '[{"id":"c0","text":"일본 SCM :","done":false},{"id":"c1","text":"베트남 SCM :","done":false},{"id":"c2","text":"Q1 교육 마무리","done":false},{"id":"c3","text":"피드백 마무리 -> 정리 -> 피드백 보완 준비 -> 완료","done":false},{"id":"c4","text":"Q2 교육 일정 준비","done":false},{"id":"c5","text":"한국 SCM :","done":false},{"id":"c6","text":"교육 자료 배포 및 교육 시작 - 교육일정 잡기","done":false},{"id":"c7","text":"지역별(국가별) 교육자료 만들기","done":false},{"id":"c8","text":"최종자료 -> Note 업데이트 완료","done":false}]'::jsonb, '2026-04-01', '2026-04-30', 'sK2TAc2baE6jjWcDK-ep_MkAAEQM', 'planner', 'planner', (select id from public.users where email='cb.park@ohmyhotel.com'));
insert into action_plans (title, description, key_result_id, objective_id, team_id, owner_id, external_assignees, status, priority, bucket, labels, checklist, start_date, due_date, external_id, external_source, data_source, created_by) values ('2026년 년간 세일즈콜 스케줄', null, '00000000-0000-4000-8000-0000000000d2', null, (select id from teams where slug='gst'), (select id from public.users where email='cb.park@ohmyhotel.com'), array['Yun Hye Yeong ̣(Jane)','Dang Minh Duc (Ben)','Son Yeong Eun (Jasmine)','HooiWem Tan (Grace)','Park Changbae (Aiden)']::text[], 'in_progress', 'important', '진행 80% 이상 Action Plan', array['Destination','2026','KR2 7000']::text[], '[{"id":"c0","text":"11월","done":false},{"id":"c1","text":"8월 :","done":false},{"id":"c2","text":"각국가별 소도시 확인 + 항공 스케줄 파악","done":false},{"id":"c3","text":"7월 : 대만, 홍콩 -> 그레이스 솔로","done":false},{"id":"c4","text":"Q1 세일즈콜 아젠다로 설정","done":false},{"id":"c5","text":"1월 세일즈콜 : 심천, 광저우, 대만, 홍콩 등에 아젠다 제공","done":false},{"id":"c6","text":"6월 세일즈콜 : 인도네시아, 태국","done":false},{"id":"c7","text":"10월","done":false},{"id":"c8","text":"Q2 아젠다 마무리","done":false},{"id":"c9","text":"12월","done":false},{"id":"c10","text":"2월 세일즈콜 : 인도 트래블마트 참가 , Make My Trip 미팅, Cliertrip 미팅","done":false},{"id":"c11","text":"2026년 마무리","done":false},{"id":"c12","text":"5월 세일즈콜 : 상하이 ITB 와 한국 트래블마트로 대체, 한국 세일즈콜","done":false},{"id":"c13","text":"9월","done":false},{"id":"c14","text":"3월 세일즈콜 : 북경 세일즈, 동남아시아 with Ben","done":false},{"id":"c15","text":"Q1 아젠다 마무리~ 전체 보고서 작성하기","done":false},{"id":"c16","text":"Q3 아젠다 마무리 - 전체보고서 작성하기","done":false}]'::jsonb, null, '2026-12-31', 'XRGQZrrUYUSIRYZk9Vcg5ckANGSN', 'planner', 'planner', (select id from public.users where email='cb.park@ohmyhotel.com'));
insert into action_plans (title, description, key_result_id, objective_id, team_id, owner_id, external_assignees, status, priority, bucket, labels, checklist, start_date, due_date, external_id, external_source, data_source, created_by) values ('Q1 베이징 비지니스 트립', '2026년 제 1차 비지니스 트립 : 중국 베이징 아젠다 : 소도시집중 + 싱가포르 플립 + 단체호텔(Hardblock)통로 만들기 통계 준비 하기 아젠다 : 고객사 확장 방문 업체 : 마펑워 등 - > 계약 진행중 중국 10대 TMC -> 差旅一号 , 시트립, 알리, DIDI, Huawei 등 있음', '00000000-0000-4000-8000-0000000000d1', null, (select id from teams where slug='gst'), (select id from public.users where email='cb.park@ohmyhotel.com'), array['HooiWem Tan (Grace)','Park Changbae (Aiden)']::text[], 'completed', 'important', '마무리', array['Business Trip','Q1','KR1 1000']::text[], '[{"id":"c0","text":"보고 완료","done":true},{"id":"c1","text":"세일즈콜 아젠다 + 통계 준비하기","done":true},{"id":"c2","text":"베이징 -> 기안서 작성학기 : 그레이스 동반","done":true},{"id":"c3","text":"베이징 업체 확인중 - 그레이스","done":true},{"id":"c4","text":"세일즈 콜 보고서 준비하기","done":true}]'::jsonb, null, '2026-03-27', 'ChVilLxLoE-BRK0iaVQAockAMb7M', 'planner', 'planner', (select id from public.users where email='cb.park@ohmyhotel.com'));
insert into action_plans (title, description, key_result_id, objective_id, team_id, owner_id, external_assignees, status, priority, bucket, labels, checklist, start_date, due_date, external_id, external_source, data_source, created_by) values ('Q1 인도네시아 비지니스 트립', '2026년 제 1차 비지니스 트립 : 인도네시아 자카르타 아젠다 : 인도네시아 3대 OTA 계약 + MG 매출 증진', '00000000-0000-4000-8000-0000000000d1', null, (select id from teams where slug='gst'), (select id from public.users where email='cb.park@ohmyhotel.com'), array['Dang Minh Duc (Ben)','HooiWem Tan (Grace)','Park Changbae (Aiden)']::text[], 'completed', 'important', '마무리', array['Business Trip','Q1','KR1 1000']::text[], '[{"id":"c0","text":"보고 완료","done":true},{"id":"c1","text":"세일즈콜 아젠다 준비하기 - 브로셔","done":true},{"id":"c2","text":"자카르타 -> 기안서 작성학기 : 벤 동반","done":true},{"id":"c3","text":"업체 리스트업 - 벤","done":true},{"id":"c4","text":"세일즈 콜 보고서 준비하기","done":true}]'::jsonb, null, '2026-03-12', 'pTCF83SZf0Wu_I3zTR9I48kABLg5', 'planner', 'planner', (select id from public.users where email='cb.park@ohmyhotel.com'));
insert into action_plans (title, description, key_result_id, objective_id, team_id, owner_id, external_assignees, status, priority, bucket, labels, checklist, start_date, due_date, external_id, external_source, data_source, created_by) values ('CRM 기획 + 의견 취합 -> 기획중', '안녕하세요. CRM 체크 후 아래와 같이 피드백 공유 드리오니 확인 부탁 드립니다. KR SCM 취합본 #1- 추가 기간 설정 (Choose Specific Period) #3- Monthly Trend 챠트 - 분기, 반년, 1년, 특정 기간별 (시즈널리티에 따른 추가 기간 설정) Trend 챠트 요청 #5- Top6 도시 -> Top 10 도시 비중 변경 요청 #6- TOP/BOTTOM 호텔 --> 나라별, 도시별 구분값 요청, 비교 기간은 특정 기간별 추가 요청 (하드블럭 시설 포함, 미포함', null, '00000000-0000-4000-8000-0000000000a1', (select id from teams where slug='gst'), (select id from public.users where email='cb.park@ohmyhotel.com'), array['Younggeun Choi (Justin)','Hyunae Noh (Julia)','Park Changbae (Aiden)','Jackie']::text[], 'completed', 'urgent', '마무리', array['System Plan','AI','2026','Q1']::text[], '[{"id":"c0","text":"개발팀 문서 작성 넘기기","done":true},{"id":"c1","text":"CTO 님 피드백 미팅 : 3월 30일","done":true},{"id":"c2","text":"허브스팟과 같이 Sales activity note 기능 필요 -콜 (전화) 메모 기능 --> To do list 기능 추가 -미팅 메모 기능 --> To do list 기능 추가","done":true},{"id":"c3","text":"Julia님 피드백 미팅 : 4월 6일","done":true},{"id":"c4","text":"인센티브 기획","done":true},{"id":"c5","text":"각 호텔별 블랙, 화이트, 맵, 언맵 등 표기 또한 채널링 블랙 확인이 가능하다면 동시 표기 요청","done":true},{"id":"c6","text":"하드블럭 기획 : 2026년 3월 20일","done":true},{"id":"c7","text":"CEO 피드백 미팅 : 4월 13일 오후 예정+ 줄리아 참여","done":true},{"id":"c8","text":"대표님 피드백 완료 - 반영","done":true}]'::jsonb, null, '2026-04-13', 'xvmKb6O110eq3vw8dcb8EMkANYtt', 'planner', 'planner', (select id from public.users where email='cb.park@ohmyhotel.com'));
