insert into critical_six (title, description, key_result_id, objective_id, team_id, owner_id, external_assignees, status, priority, completion_criteria, blocker, completed_at, due_date, external_id, external_source, created_by) values ('DI 팀 업무 최적화 - Task 배분 분석', '일론 머스크의 ''제1원칙 사고(First Principles Thinking)''는 복잡한 문제를 가장 기본적인 구성 요소나 근본적인 진실로 분해한 뒤, 기존의 가정이나 비유에 의존하지 않고 그 핵심 진실로부터 새로운 해결책을 구축하는 사고방식입니다.', '00000000-0000-4000-8000-0000000000d3', '00000000-0000-4000-8000-0000000000a1', (select id from teams where slug='gst'), (select id from public.users where email='cb.park@ohmyhotel.com'), array['Park Changbae (Aiden)']::text[], 'completed', 'important', '자동화 하기 · DI 전체 Task 분배 시간 파악 및 매뉴얼 업무, 혹은 비 효율적인 업무 파악하기 · 트레이스 Task 리스트 작업 실시 · DI팀 TASK 분석 중, · Data Setup & Update (Hotel / Room / Rate / Content) 47% 점유 · RPA + AI + Develop 으로 해결 가능한 내용 찾아서 처리', null, ('2025-12-26'::timestamptz), '2025-12-26', 'R7QV8jsjskuVeJfb2xnCyckADxTi', 'planner', (select id from public.users where email='cb.park@ohmyhotel.com'));
