insert into critical_six (title, description, key_result_id, objective_id, team_id, owner_id, external_assignees, status, priority, completion_criteria, blocker, completed_at, due_date, external_id, external_source, created_by) values ('Convergent QPS 상향 관련 보고', 'Convergent: 현재는 여러 일본 공급사들과 협업하고 있으며, 각 업체로부터 비교적 좋은 수준의 신용 한도(무보증)를 제공받고 있다고 함. 일부 파트너사의 경우에는 보증금 방식으로 최소 1:3, 많게는 1:5 비율의 credit limit를 제공하고 있음 만약 보증금을 추가하는 방식으로 진행할 경우, 우리에서는 어느 정도 비율의 credit line을 제공해 주실 수 있는지, 또한 보증금은 어느 수준이 적절하다고 보시는지 문의드려왔어요', '00000000-0000-4000-8000-0000000000d3', '00000000-0000-4000-8000-0000000000a1', (select id from teams where slug='gst'), (select id from public.users where email='cb.park@ohmyhotel.com'), array['HooiWem Tan (Grace)','Park Changbae (Aiden)']::text[], 'completed', 'important', 'Grace 피드백 완료 · Convergent Credit : USD10,000 -> 100배 중 · Grace 고객사 체크', null, ('2025-12-24'::timestamptz), '2025-12-24', 'YqJ0mTCWEk2f1CwTaCDeaMkAIFlD', 'planner', (select id from public.users where email='cb.park@ohmyhotel.com'));
